package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.DatedSetting;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Takes a statement of the person: records their due-total now (the sum of the due of their claims that
 *  count live (open ones dated within a hold of theirs, and not bound, do not), n/a ones skipped, at most the sheet's cap; n/a when their grade has no rate on the sheet's today and none of
 *  those claims keeps a settled or bound figure, or a live one at a grade no longer in force or dated on or before the sheet's today) on the sheet's today, and binds each counting claim
 *  to its rate figure under the due it shows now (its late charge and the floor are never bound); a claim that does not
 *  count live is unbound. */
public class TakeStatement {
    public void take(@Val Person person, PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings) {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        DatedSetting floor = settings.floor(sheetId);
        Dues.Late late = settings.late(sheetId, today);
        List<Claim> own = claims.listOf(sheetId, person.getId());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int bound = 0;
        for (Claim c : own) {
            if (!person.countsLive(c)) {
                c.bind(false, null);
            } else {
                String grade = person.gradeOn(c.getDate());
                Rate rate = rates.find(sheetId, grade, LocalDate.parse(c.getDate()));
                String live = rate == null ? null : Dues.of(c.getAmount(), rate.pct(), late.rounding(c.getRoundDate()));
                String shown = Dues.shown(c, live, floor.on(c.getDate()), late);
                kept |= c.getSettledDue() != null || c.isBound()
                        || (rate != null && (!grade.equals(person.getGrade())
                                || !LocalDate.parse(c.getDate()).isAfter(today)));
                if (shown != null) total = total.add(new BigDecimal(shown));
                // The rate figure under it is bound; its late charge and floor keep following the sheet's today.
                c.bind(true, c.due(live));
                bound++;
            }
            claims.updateBinding(c);
        }
        boolean na = rates.find(sheetId, person.getGrade(), today) == null && !kept;
        BigDecimal cap = settings.cap(sheetId);
        if (cap != null && total.compareTo(cap) > 0) total = cap.setScale(2);
        person.stated(na ? null : total.toPlainString(), today.toString(), bound);
        people.updateStatements(person);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.setting.DatedSetting;

/** A claim's due figure. */
public final class Dues {
    private Dues() {
    }

    /** What a late charge goes by: the sheet's late percent by date (a charge goes by the one in force on each 30-day boundary) and its today (a claim's due-by is its own); and the
     *  sheet's policy date (its today when blank), which decides how a claim's live figures round. */
    public record Late(DatedSetting pct, LocalDate today, LocalDate policy) {

        /** How the live figures of a claim round by its round date ({@link Claim#getRoundDate}):
         *  half up before the policy date, half to even on or after it. */
        public RoundingMode rounding(String roundDate) {
            return LocalDate.parse(roundDate).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
        }
    }

    /** A claim's rate figure: an amount times a percent, divided by 100, rounded ({@code rounding}) to
     *  two decimals (no floor: that is applied last, by {@link #shown}). */
    public static String of(String amount, String pct, RoundingMode rounding) {
        return new BigDecimal(amount).multiply(new BigDecimal(pct))
                .divide(BigDecimal.valueOf(100), 2, rounding).toPlainString();
    }

    /** Whether a claim's amount makes it a correction: it is negative. */
    public static boolean isCorrection(String amount) {
        return new BigDecimal(amount).signum() < 0;
    }

    /** The late charge on a claim's figure: for each full 30 days its open (OPEN or PENDING) claim is past its
     *  due-by (fixed when it was added) on the sheet's today, the late percent in force on that boundary date
     *  (its due-by plus 30, 60, 90 ... days) of it, each rounded by the policy date to two decimals, added up;
     *  none (0.00) when it is not overdue (a deferred claim never is), or on a correction. */
    public static BigDecimal charge(Claim claim, String figure, Late late) {
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        if (figure == null || isCorrection(claim.getAmount()) || !ClaimStatus.isOpen(claim.getStatus()) || claim.isDeferred()) return total;
        LocalDate dueBy = LocalDate.parse(claim.getDueBy());
        long periods = Math.max(0, ChronoUnit.DAYS.between(dueBy, late.today())) / 30;
        RoundingMode rounding = late.rounding(claim.getRoundDate());
        for (long k = 1; k <= periods; k++) {
            String pct = late.pct().on(dueBy.plusDays(30 * k).toString());
            if (pct == null) continue;
            total = total.add(new BigDecimal(figure).multiply(new BigDecimal(pct))
                    .divide(BigDecimal.valueOf(100), 2, rounding));
        }
        return total;
    }

    /** The due a claim shows: the one fixed when settled, else its figure (bound by a statement, else
     *  {@code live}; null: none) with its late charge added on top, and at least {@code floor}, the sheet's
     *  floor in force on the claim's date (null: none), applied last (a correction has no floor). */
    public static String shown(Claim claim, String live, String floor, Late late) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        String figure = claim.due(live);
        if (figure == null) return null;
        BigDecimal due = new BigDecimal(figure).add(charge(claim, figure, late));
        if (floor != null && !isCorrection(claim.getAmount())) due = due.max(new BigDecimal(floor).setScale(2));
        return due.toPlainString();
    }
}
package net.officefloor.hq.app.claim;

import com.fasterxml.jackson.annotation.JsonIgnore;
import java.util.List;

/** A claim of a person: an amount (two decimals, as text), a date (yyyy-MM-dd), a note and a status
 *  (a {@link ClaimStatus} name), and its number on the sheet (given when opened and kept when voided;
 *  none while a draft: the sheet-wide number, or {@code <period>-<n>} while period numbering is in force), its settled due (fixed when settled; none otherwise, or when there was no rate), and
 *  who opened it (none while a draft), and whether its person's last statement bound it, with the
 *  figure it bound (none when it had none): a bound claim shows and totals that figure. A correction (a
 *  negative amount) keeps the number of the SETTLED claim of its person it corrects (none otherwise). */
public class Claim {
    private final long id;
    private final String sheetId;
    private long personId;
    private String amount;
    private String date;
    private String note;
    private String status;
    private String number;
    private String settledDue;
    private String openedBy;
    private boolean stated;
    private String statedDue;
    private String corrects;
    private String roundDate;
    private String dueBy;
    private List<String> log = List.of();
    private String deferredUntil;
    private boolean deferred;
    private int proofs;
    private String splitFrom;
    private boolean reversal;
    private String lockedBy;
    private boolean lateEntry;

    public Claim(long id, String sheetId, long personId, String amount, String date, String note,
            String status, String number, String settledDue, String openedBy) {
        this(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, false, null);
    }

    public Claim(long id, String sheetId, long personId, String amount, String date, String note,
            String status, String number, String settledDue, String openedBy, boolean stated,
            String statedDue) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
        this.stated = stated;
        this.statedDue = statedDue;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public void setPersonId(long personId) { this.personId = personId; }
    public String getAmount() { return amount; }
    public void setAmount(String amount) { this.amount = amount; }
    public String getDate() { return date; }
    public void setDate(String date) { this.date = date; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
    public String getNumber() { return number; }
    public void setNumber(String number) { this.number = number; }
    public String getSettledDue() { return settledDue; }
    /** Whether this change voided a SETTLED claim, reversing its frozen figure (not stored). */
    @JsonIgnore
    public boolean isReversal() { return reversal; }
    public void setReversal(boolean reversal) { this.reversal = reversal; }
    public void setSettledDue(String settledDue) { this.settledDue = settledDue; }

    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }

    public String getCorrects() { return corrects; }
    public void setCorrects(String corrects) { this.corrects = corrects; }

    /** The date its figures round by (see {@link Dues.Late#rounding}): its own date, or for a
     *  correction the date of the claim it corrects. */
    public String getRoundDate() { return roundDate == null ? date : roundDate; }
    public void setRoundDate(String roundDate) { this.roundDate = roundDate; }

    /** Its due-by (yyyy-MM-dd), fixed when it was added: its date then plus the terms of its
     *  person's grade in force on that date. */
    public String getDueBy() { return dueBy; }
    public void setDueBy(String dueBy) { this.dueBy = dueBy; }

    /** Its status log, oldest first (see {@link ClaimLogRepository}). */
    public List<String> getLog() { return log; }
    public void setLog(List<String> log) { this.log = log; }

    /** The date it was last deferred until (yyyy-MM-dd; none: never deferred). */
    public String getDeferredUntil() { return deferredUntil; }

    /** Whether it is deferred on the sheet's today: OPEN and deferred until a later date. A deferred
     *  claim counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferred() { return deferred; }

    public void setDeferral(String deferredUntil, boolean deferred) {
        this.deferredUntil = deferredUntil;
        this.deferred = deferred;
    }

    /** Defer it until a date after the sheet's today. */
    public void defer(String until) {
        setDeferral(until, true);
    }

    /** How many proofs it has (0 until one is added). */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }

    /** The number of the claim it was split from (none: not split off a claim). */
    public String getSplitFrom() { return splitFrom; }
    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }

    /** The user whose open editor locks it for everyone else (none: unlocked). */
    public String getLockedBy() { return lockedBy; }
    public void setLockedBy(String lockedBy) { this.lockedBy = lockedBy; }

    /** Whether it was added while the period its date falls in was soft-closed. */
    public boolean isLateEntry() { return lateEntry; }
    public void setLateEntry(boolean lateEntry) { this.lateEntry = lateEntry; }

    public boolean isStated() { return stated; }
    public String getStatedDue() { return statedDue; }

    /** Bind to a figure (null: none), or unbind when not {@code stated}. */
    public void bind(boolean stated, String statedDue) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
    }

    /** Whether it counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED do. */
    @JsonIgnore
    public boolean isCounting() {
        return ClaimStatus.isOpen(status) || ClaimStatus.SETTLED.name().equals(status);
    }

    /** Whether a statement's figure binds it now: it was bound to one and is not PENDING (a PENDING
     *  claim keeps its binding, but shows and totals its live figure until it is rejected). */
    @JsonIgnore
    public boolean isBound() {
        return stated && statedDue != null && !ClaimStatus.PENDING.name().equals(status);
    }

    /** The due it shows: the one fixed when settled, else the one bound by a statement (not while
     *  PENDING), else {@code live} (the amount at the rate in force on its date; null: none). */
    public String due(String live) {
        if (settledDue != null) return settledDue;
        return stated && !ClaimStatus.PENDING.name().equals(status) ? statedDue : live;
    }

    /** The audit suffix: {@code " number=<n>"} for a claim that has a number. */
    @JsonIgnore
    public String getAuditNumber() {
        return number == null ? "" : " number=" + number;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Each claim's status log: one line per status it has had, oldest first, as
 *  {@code <STATUS> by <user> on <date> due=<due>} (the sheet's today and the due it showed then; n/a: none). */
@Repository
public class ClaimLogRepository {

    private final JdbcTemplate jdbc;
    private final PersonRepository people;
    private final RateRepository rates;
    private final SettingRepository settings;
    private final SheetRepository sheets;

    public ClaimLogRepository(JdbcTemplate jdbc, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Log the claim's status now: by the user, on the sheet's today, with the due it shows now. */
    public void record(Claim claim, String by) {
        String sheetId = claim.getSheetId();
        LocalDate today = sheets.today(sheetId);
        Person person = people.find(sheetId, claim.getPersonId());
        Rate rate = person == null ? null : rates.find(sheetId, person.gradeOn(claim.getDate()),
                LocalDate.parse(claim.getDate()));
        Dues.Late late = settings.late(sheetId, today);
        String due = Dues.shown(claim, rate == null ? null : Dues.of(claim.getAmount(), rate.pct(),
                late.rounding(claim.getRoundDate())), settings.floor(sheetId).on(claim.getDate()), late);
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due) VALUES (?, ?, ?, ?, ?, ?)",
                sheetId, claim.getId(), claim.getStatus(), by == null ? "" : by, today,
                due == null ? null : new BigDecimal(due));
    }

    /** The sheet's log lines by claim id, oldest first. */
    public Map<Long, List<String>> linesOf(String sheetId) {
        Map<Long, List<String>> lines = new HashMap<>();
        jdbc.query("SELECT claim_id, status, by_user, on_date, due FROM claim_log WHERE sheet_id = ? ORDER BY id",
                (rs) -> {
                    BigDecimal due = rs.getBigDecimal("due");
                    lines.computeIfAbsent(rs.getLong("claim_id"), (k) -> new ArrayList<>())
                            .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
                                    + rs.getObject("on_date", LocalDate.class) + " due="
                                    + (due == null ? "n/a" : due.setScale(2).toPlainString()));
                }, sheetId);
        return lines;
    }

    /** The day the claim was last logged SETTLED (null: never). */
    public LocalDate settledOn(String sheetId, long claimId) {
        List<LocalDate> dates = jdbc.query("SELECT on_date FROM claim_log WHERE sheet_id = ? AND claim_id = ? "
                + "AND status = 'SETTLED' ORDER BY id DESC", (rs, i) -> rs.getObject("on_date", LocalDate.class),
                sheetId, claimId);
        return dates.isEmpty() ? null : dates.get(0);
    }

    /** Each logged claim's status at the end of the day, as its log records it: the last status
     *  logged on or before it, or null when it was added after it. Claims with no log are absent. */
    public Map<Long, String> statusesOn(String sheetId, LocalDate date) {
        Map<Long, String> statuses = new HashMap<>();
        jdbc.query("SELECT claim_id, status, on_date FROM claim_log WHERE sheet_id = ? ORDER BY id",
                (rs) -> {
                    long claimId = rs.getLong("claim_id");
                    if (!rs.getObject("on_date", LocalDate.class).isAfter(date)) {
                        statuses.put(claimId, rs.getString("status"));
                    } else {
                        statuses.putIfAbsent(claimId, null);
                    }
                }, sheetId);
        return statuses;
    }

    /** Give each claim its log lines. */
    public List<Claim> withLogs(String sheetId, List<Claim> claims) {
        Map<Long, List<String>> lines = linesOf(sheetId);
        for (Claim c : claims) c.setLog(lines.getOrDefault(c.getId(), List.of()));
        return claims;
    }
}
