    }

    /** Whether the live rules leave the claim out whatever its status counts: it is deferred, or an
     *  open (OPEN or PENDING) claim that no statement bound, dated within one of their holds or of a
     *  person whose retirement date the sheet's today has reached. */
    public boolean leftOutLive(Claim claim) {
        return claim.isDeferred()
                || (ClaimStatus.isOpen(claim.getStatus()) && !claim.isStated()
                        && (isRetiredReached() || holds.stream().anyMatch((h) -> h.covers(claim.getDate()))));
    }

    /** Whether a claim on this date is refused: the person is retired from a date before it. */
    public boolean retiredBefore(java.time.LocalDate date) {
        return retiredFrom != null && date.isAfter(java.time.LocalDate.parse(retiredFrom));
    }

    /** Record a statement just taken: its due-total (null: n/a), date and how many claims it bound. */
    public void stated(String total, String date, int claims) {
        this.statementCount++;
        this.statedTotal = total == null ? "n/a" : total;
        this.statementDate = date;
        this.statedClaims = claims;
    }

    /** Cancel their last statement: the count goes down by one and they show the one before it
     *  (null total and date: none), keeping the cancelled one's due-total for its audit line. */
    public void unstated(String total, String date) {
        this.cancelledTotal = this.statedTotal;
        this.statementCount--;
        this.statedTotal = date == null ? null : total == null ? "n/a" : total;
        this.statementDate = date;
    }

    @JsonIgnore
    public String getCancelledTotal() { return cancelledTotal; }

    @JsonIgnore
    public int getStatedClaims() { return statedClaims; }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** A steward cancels the person's last statement: the claims it bound (every claim of theirs bound
 *  now, as each statement rebinds or unbinds all of them) become live again, a figure bound by a
 *  statement before it not restored; the count goes down by one and they show the statement before
 *  it (or none). Refused for anyone but a steward, and for a person with no statement. */
public class CancelStatement {
    public void cancel(@RequestParam(name = "by", required = false) String by, @Val Person person,
            PersonRepository people, ClaimRepository claims, RoleRepository roles) throws InvalidPersonException {
        String sheetId = person.getSheetId();
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, by == null ? "" : by))) {
            throw new InvalidPersonException("Only a steward can cancel a statement");
        }
        if (person.getStatementCount() <= 0) {
            throw new InvalidPersonException("The person has no statement to cancel");
        }
        for (Claim c : claims.listOf(sheetId, person.getId())) {
            if (c.isStated()) {
                c.bind(false, null);
                claims.updateBinding(c);
            }
        }
        people.cancelStatement(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a statement that went through is recorded. */
public class RecordStatement {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Person person, Audit audit) {
        audit.record("STATEMENT sheet=" + person.getSheetId() + " by=" + (by == null ? "" : by)
                + " name=" + person.getName() + " due-total=" + person.getStatedTotal()
                + " claims=" + person.getStatedClaims());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId,
            @PathVariable("personId") long personId, PersonRepository people,
            Out<Person> person) throws PersonNotFoundException {
        Person found = people.find(sheetId.trim(), personId);
        if (found == null) {
            throw new PersonNotFoundException(personId);
        }
        person.set(found);
    }
}
