    };

    private final JdbcTemplate jdbc;

    public PersonRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's people in the order they were added, each with their patrons. */
    public List<Person> list(String sheetId) {
        List<Person> people = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? ORDER BY id",
                ROW, sheetId);
        Map<Long, Person> byId = new HashMap<>();
        people.forEach((p) -> byId.put(p.getId(), p));
        withGrades(sheetId, people);
        withHolds(sheetId, people);
        jdbc.query("SELECT person_id, patron_id FROM person_patron WHERE sheet_id = ? ORDER BY added_at, patron_id",
                (rs) -> {
                    Person p = byId.get(rs.getLong("person_id"));
                    if (p != null) {
                        p.getPatronIds().add(rs.getLong("patron_id"));
                    }
                }, sheetId);
        return people;
    }

    public Person find(String sheetId, long id) {
        Person person = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?",
                ROW, sheetId, id).stream().findFirst().orElse(null);
        if (person != null) {
            person.setPatronIds(new ArrayList<>(jdbc.queryForList(
                    "SELECT patron_id FROM person_patron WHERE sheet_id = ? AND person_id = ? ORDER BY added_at, patron_id",
                    Long.class, sheetId, id)));
            withGrades(sheetId, List.of(person));
            withHolds(sheetId, List.of(person));
        }
        return person;
    }

    /** Give each person their grades, by from-date (none first), and the one in force on the sheet's today. */
    private void withGrades(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        LocalDate today = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", LocalDate.class, sheetId)
                .stream().findFirst().orElse(LocalDate.now());
        Map<Long, List<GradeFrom>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, grade, from_date FROM person_grade WHERE sheet_id = ? ORDER BY person_id, from_key",
                (rs) -> {
                    LocalDate from = rs.getObject("from_date", LocalDate.class);
                    grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new GradeFrom(rs.getString("grade"), from == null ? null : from.toString()));
                }, sheetId);
        people.forEach((p) -> p.setGrades(grades.getOrDefault(p.getId(), new ArrayList<>()), today));
    }

    /** Give each person their holds, in the order they were added. */
    private void withHolds(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY person_id, id",
                (rs) -> {
                    LocalDate to = rs.getObject("to_date", LocalDate.class);
                    holds.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new Hold(rs.getObject("from_date", LocalDate.class).toString(),
                                    to == null ? null : to.toString()));
                }, sheetId);
        people.forEach((p) -> p.setHolds(holds.getOrDefault(p.getId(), new ArrayList<>())));
    }

    /** Name the patron as one of the person's patrons. */
    public void addPatron(Person person, Person patron, String user) {
        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, added_by) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), patron.getId(), user);
        person.getPatronIds().add(patron.getId());
    }

    /** The person on the sheet with this name, compared ignoring case and surrounding spaces; null when none. */
    public Person findByName(String sheetId, String name) {
        Person found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?))",
                ROW, sheetId, name).stream().findFirst().orElse(null);
        return found == null ? null : find(sheetId, found.getId());
    }

    /** Whether another person on the sheet already has this name, compared ignoring case and surrounding spaces. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND (? IS NULL OR id <> ?)",
                Integer.class, sheetId, name, exceptId, exceptId);
        return n != null && n > 0;
    }

    public Person add(String sheetId, String name, String grade, String user) {
        return add(sheetId, name, grade, null, user);
    }

    /** Add a person with their grade (from the beginning of time) and own terms (null: none). */
    public Person add(String sheetId, String name, String grade, Integer terms, String user) {
        GeneratedKeyHolder key = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, created_by, terms) VALUES (?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setString(3, user);
            ps.setObject(4, terms);
            return ps;
        }, key);
        long id = key.getKey().longValue();
        // The first grade a person is given applies from the beginning of time.
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date, set_by) VALUES (?, ?, ?, NULL, ?)",
                sheetId, id, grade, user);
        Person person = new Person(id, sheetId, name, grade, 0);
        person.getGrades().add(new GradeFrom(grade, null));
        person.setTerms(terms);
        return person;
    }

    /** Record the grade the person was just given (see {@link Person#giveGrade}), replacing the one
     *  with the same from-date. */
    public void saveGrade(Person person, GradeFrom given, String user) {
        LocalDate from = given.from() == null ? null : LocalDate.parse(given.from());
        if (from == null) {
            jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date IS NULL",
                    person.getSheetId(), person.getId());
        } else {
            jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date = ?",
                    person.getSheetId(), person.getId(), from);
        }
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date, set_by) VALUES (?, ?, ?, ?, ?)",
                person.getSheetId(), person.getId(), given.grade(), from, user);
    }

    /** Save the person over the version it was loaded at, raising the version; false (nothing
     *  written) when someone else has saved the person since. */
    public boolean update(Person person) {
        int n = jdbc.update(
                "UPDATE person SET name = ?, terms = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
                person.getName(), person.getTerms(), person.getSheetId(), person.getId(), person.getVersion());
        if (n == 0) {
            return false;
        }
        person.setVersion(person.getVersion() + 1);
        return true;
    }

    /** Save the statement just taken of the person (not an edit: the version stays). */
    public void updateStatements(Person person) {
        saveStatements(person);
        jdbc.update("INSERT INTO person_statement (sheet_id, person_id, stated_total, statement_date) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), person.getStatedTotal(), LocalDate.parse(person.getStatementDate()));
    }

    /** Drop the person's last statement kept, and load the one before it into the person (none: they
     *  show no statement); their count goes down by one (not an edit: the version stays). */
    public void cancelStatement(Person person) {
        List<Long> kept = jdbc.queryForList(
                "SELECT id FROM person_statement WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC LIMIT 2",
                Long.class, person.getSheetId(), person.getId());
        if (!kept.isEmpty()) {
            jdbc.update("DELETE FROM person_statement WHERE id = ?", kept.get(0));
        }
        String[] before = kept.size() < 2 ? null : jdbc.queryForObject(
                "SELECT stated_total, statement_date FROM person_statement WHERE id = ?",
                (rs, n) -> new String[] { rs.getString("stated_total"),
                        rs.getObject("statement_date", LocalDate.class).toString() }, kept.get(1));
        person.unstated(before == null ? null : before[0], before == null ? null : before[1]);
        saveStatements(person);
    }

    private void saveStatements(Person person) {
        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE sheet_id = ? AND id = ?",
                person.getStatementCount(), person.getStatedTotal(),
                person.getStatementDate() == null ? null : LocalDate.parse(person.getStatementDate()),
                person.getSheetId(), person.getId());
    }

    /** Save the person's retirement date (not an edit: the version stays). */
    public void updateRetired(Person person) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?",
                LocalDate.parse(person.getRetiredFrom()), person.getSheetId(), person.getId());
    }

    /** Add a hold on the person (not an edit: the version stays). */
    public void addHold(Person person, Hold hold, String user) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, held_by) VALUES (?, ?, ?, ?, ?)",
                person.getSheetId(), person.getId(), LocalDate.parse(hold.from()),
                hold.to() == null ? null : LocalDate.parse(hold.to()), user);
        person.getHolds().add(hold);
    }
}
package net.officefloor.hq.app.person;

/** A hold on a person: from its from-date (yyyy-MM-dd) to its to-date (null: open-ended), both included. */
public record Hold(String from, String to) {

    /** Whether the date (yyyy-MM-dd) falls within the hold. */
    public boolean covers(String date) {
        return from.compareTo(date) <= 0 && (to == null || date.compareTo(to) <= 0);
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SettingRepository {

    /** The clerk limit: the largest due a clerk may settle (two decimals; blank: no limit). */
    public static final String CLERK_LIMIT = "clerk-limit";

    /** The proof threshold: a claim whose due is above the one in force on its date cannot be settled
     *  or approved without a proof (two decimals; blank: none). */
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** The cap: the most a person's due-total can be (two decimals; blank: no cap). */
    public static final String CAP = "cap";

    /** The floor: the least a claim's live due can be (two decimals). */
    public static final String FLOOR = "floor";

    /** The terms: the number of days after its date by which a claim is due (a whole number). */
    public static final String TERMS = "terms";

    /** A grade's own terms ({@code terms-<grade>}; blank: the sheet's terms). */
    public static final String TERMS_OF_GRADE = "terms-";

    /** The late percent: the share of an overdue claim's figure it gains for every full 30 days
     *  it is overdue (two decimals). */
    public static final String LATE_PCT = "late-pct";

    /** The policy date (yyyy-MM-dd; blank: the sheet's today): a claim dated before it rounds half
     *  up, one on or after it half to even. */
    public static final String POLICY_DATE = "policy-date";

    /** The period numbering date (yyyy-MM-dd; blank: off): once the sheet's today is on or after it,
     *  a claim opened is numbered within its period. */
    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";

    /** The grace days (a whole number; blank: off): when the sheet's today changes, an open period
     *  whose to-date plus them is before the new today is closed. */
    public static final String GRACE_DAYS = "grace-days";

    /** The late percent until it is first set. */
    public static final String DEFAULT_LATE_PCT = "0.00";

    /** The terms until they are first set. */
    public static final String DEFAULT_TERMS = "14";

    /** The floor until it is first set. */
    public static final String DEFAULT_FLOOR = "1.00";

    /** Whether a key is dated: every key that carries a figure (the policy date, the period
     *  numbering date, the grace days and the permission matrix are not). */
    public static boolean isDated(String key) {
        return !POLICY_DATE.equals(key) && !GRACE_DAYS.equals(key) && !PERIOD_NUMBERING_FROM.equals(key) && !Permissions.isKey(key);
    }

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;

    public SettingRepository(JdbcTemplate jdbc, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /** Every value recorded for the sheet's settings, by key, then by from-date (none first). */
    public List<Setting> list(String sheetId) {
        return jdbc.query("SELECT sheet_id, setting, val, from_date FROM sheet_setting WHERE sheet_id = ? "
                + "ORDER BY setting, from_key", (rs, n) -> row(rs), sheetId);
    }

    private static Setting row(ResultSet rs) throws SQLException {
        LocalDate from = rs.getObject("from_date", LocalDate.class);
        return new Setting(rs.getString("sheet_id"), rs.getString("setting"),
                rs.getString("val") == null ? "" : rs.getString("val"), from == null ? null : from.toString());
    }

    /** The values recorded for a key, with its value before every from-date ({@code start}). */
    public DatedSetting dated(String sheetId, String key, String start) {
        return new DatedSetting(jdbc.query("SELECT sheet_id, setting, val, from_date FROM sheet_setting "
                + "WHERE sheet_id = ? AND setting = ?", (rs, n) -> row(rs), sheetId, key), start);
    }

    /** An undated setting's value; null when blank or never set. */
    public String find(String sheetId, String key) {
        return dated(sheetId, key, null).on("9999-12-31");
    }

    /** The sheet's clerk limit in force on its today; null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        String value = dated(sheetId, CLERK_LIMIT, null).on(sheets.today(sheetId).toString());
        return value == null ? null : new BigDecimal(value);
    }

    /** The sheet's proof threshold in force on a date (yyyy-MM-dd); null when there is none. */
    public BigDecimal proofThreshold(String sheetId, String date) {
        String value = dated(sheetId, PROOF_THRESHOLD, null).on(date);
        return value == null ? null : new BigDecimal(value);
    }

    /** The sheet's cap in force on its today; null when there is none. */
    public BigDecimal cap(String sheetId) {
        String value = dated(sheetId, CAP, null).on(sheets.today(sheetId).toString());
        return value == null ? null : new BigDecimal(value);
    }

    /** The sheet's floor (two decimals) by date: a claim goes by the one in force on its date. */
    public DatedSetting floor(String sheetId) {
        return dated(sheetId, FLOOR, DEFAULT_FLOOR);
    }

    /** The terms (whole days) of a grade in force on a date: its own, else the sheet's (a null
     *  grade: the sheet's). */
    public int terms(String sheetId, String grade, String date) {
        String value = grade == null ? null : dated(sheetId, TERMS_OF_GRADE + grade, null).on(date);
        return Integer.parseInt(value != null ? value : dated(sheetId, TERMS, DEFAULT_TERMS).on(date));
    }

    /** The terms (whole days) of a claim of the person on a date: their own, else those of their
     *  grade in force on it, else the sheet's, each as in force on the date (a null person: the sheet's). */
    public int terms(String sheetId, net.officefloor.hq.app.person.Person person, String date) {
        if (person != null && person.getTerms() != null) {
            return person.getTerms();
        }
        return terms(sheetId, person == null ? null : person.gradeOn(date), date);
    }

    /** The sheet's late percent (two decimals) by date: a late charge goes by the one in force on each 30-day boundary. */
    public DatedSetting latePct(String sheetId) {
        return dated(sheetId, LATE_PCT, DEFAULT_LATE_PCT);
    }

    /** The sheet's policy date: the one set, else its {@code today}. */
    public LocalDate policyDate(String sheetId, LocalDate today) {
        String value = find(sheetId, POLICY_DATE);
        return value == null ? today : LocalDate.parse(value);
    }

    /** The sheet's period numbering date; null when off. */
    public LocalDate periodNumberingFrom(String sheetId) {
        String value = find(sheetId, PERIOD_NUMBERING_FROM);
        return value == null ? null : LocalDate.parse(value);
    }

    /** What a claim's late charge and rounding go by on the sheet now. */
    public Dues.Late late(String sheetId, LocalDate today) {
        return new Dues.Late(latePct(sheetId), today, policyDate(sheetId, today));
    }

    /** Record the setting's value (null: blank) from the from-date (null: from the beginning of time,
     *  for an undated key), replacing the one recorded from the same from-date. */
    public Setting set(String sheetId, String key, String value, LocalDate from, String user) {
        jdbc.update("DELETE FROM sheet_setting WHERE sheet_id = ? AND setting = ? AND from_key = ?",
                sheetId, key, from == null ? LocalDate.of(1, 1, 1) : from);
        jdbc.update("INSERT INTO sheet_setting (sheet_id, setting, val, from_date, set_by, set_at) "
                + "VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)", sheetId, key, value, from, user);
        return new Setting(sheetId, key, value == null ? "" : value, from == null ? null : from.toString());
    }
}
package net.officefloor.hq.app.setting;

import java.util.List;

/** A dated setting's values by from-date, and the value it has before every from-date ({@code start};
 *  null: none). */
public record DatedSetting(List<Setting> values, String start) {

    /** The value in force on the date (yyyy-MM-dd): the one with the latest from-date on or before
     *  it (none: from the beginning of time), else the starting value; null when blank or none. */
    public String on(String date) {
        Setting found = null;
        for (Setting s : values) {
            if (s.from() != null && s.from().compareTo(date) > 0) continue;
            if (found == null || nz(found.from()).compareTo(nz(s.from())) < 0) found = s;
        }
        if (found == null) return start;
        return found.value().isEmpty() ? null : found.value();
    }

    private static String nz(String from) {
        return from == null ? "" : from;
    }
}

