rep('''                  <button type="button" data-testid="person-statement" disabled={statement.isPending}''',
'''                  <input type="date" data-testid="person-statement-asof" value={asOfDates[p.id] ?? ''}
                    onChange={(e) => {
                      setAsOfDates((d) => ({ ...d, [p.id]: e.target.value }));
                      statement.reset();
                    }} />{' '}
                  <button type="button" data-testid="person-statement" disabled={statement.isPending}''')
rep('''{statement.isError && statement.variables === p.id && (''','''{statement.isError && statement.variables?.id === p.id && (''')
open(p,'w').write(s)
